import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"ADR-005: Versioned Backups and Rollback","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-versioned-backups.md","filePath":"adr/005-versioned-backups.md"}'),r={name:"adr/005-versioned-backups.md"};function s(n,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-005-versioned-backups-and-rollback" tabindex="-1">ADR-005: Versioned Backups and Rollback <a class="header-anchor" href="#adr-005-versioned-backups-and-rollback" aria-label="Permalink to &quot;ADR-005: Versioned Backups and Rollback&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-05 <strong>Status:</strong> Accepted</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Users need confidence that importing bad data or making mistakes won&#39;t permanently corrupt their financial history. ADR-001 mentioned a simple JSON export; this ADR extends that to versioned, restorable checkpoints.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="backup-types" tabindex="-1">Backup Types <a class="header-anchor" href="#backup-types" aria-label="Permalink to &quot;Backup Types&quot;">​</a></h3><ul><li><strong>JSON export</strong> — full data export (all tables) as a single JSON file</li><li><strong>CSV export</strong> — per-account transaction and holdings exports</li><li><strong>Database checkpoints</strong> — date-stamped <code>.db</code> snapshots stored locally (not in git)</li></ul><h3 id="checkpoint-triggers" tabindex="-1">Checkpoint Triggers <a class="header-anchor" href="#checkpoint-triggers" aria-label="Permalink to &quot;Checkpoint Triggers&quot;">​</a></h3><ul><li>Manual: user clicks &quot;Create checkpoint&quot; in Settings</li><li>Automatic: before every import (so imports are always reversible)</li></ul><h3 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h3><ul><li>Settings &gt; Data &amp; Backups shows a list of all checkpoints with date, label, and size</li><li>&quot;Restore&quot; button on any checkpoint replaces the current <code>libertas.db</code> with that snapshot</li><li>Current state is auto-checkpointed before rollback so the rollback itself is reversible</li></ul><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><ul><li>Checkpoints stored in <code>/data/backups/</code> (gitignored)</li><li><code>backups</code> table in DB tracks metadata (path, date, label, size)</li><li>Old checkpoints beyond 30 days auto-pruned (configurable)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>New <code>backups</code> router in backend</li><li><code>/data/backups/</code> directory created on first run, added to <code>.gitignore</code></li><li><code>backups</code> table added to DB</li><li>Import flow always creates a checkpoint before committing</li><li>Settings page gains &quot;Data &amp; Backups&quot; section</li></ul>',16)])])}const b=a(r,[["render",s]]);export{h as __pageData,b as default};
